* { box-sizing: border-box; }
body { margin: 0; background: var(--jk-color-canvas); color: var(--jk-color-text); font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 14px; line-height: 1.45; }
button, select, textarea { font: inherit; color: inherit; }
.refund-workbench { min-height: 100vh; padding: var(--jk-space-4); }
.page-header { display: flex; align-items: flex-end; justify-content: space-between; gap: var(--jk-space-4); max-width: 1333px; margin: 0 auto var(--jk-space-4); }
.eyebrow { margin: 0 0 var(--jk-space-2); color: var(--jk-color-muted); font-size: 12px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
h1, h2, h3, p { margin-top: 0; }
h1 { margin-bottom: var(--jk-space-2); font-size: 24px; line-height: 1.2; }
h2 { margin-bottom: var(--jk-space-3); font-size: 16px; }
h3 { margin-bottom: var(--jk-space-2); font-size: 14px; }
.subtitle, .muted, .helper { color: var(--jk-color-muted); }
.subtitle, .helper { margin-bottom: 0; }
.queue-count { white-space: nowrap; color: var(--jk-color-muted); }
.workspace { display: grid; grid-template-columns: minmax(230px, 280px) minmax(430px, 1fr) minmax(300px, 360px); gap: var(--jk-space-4); max-width: 1333px; margin: 0 auto; align-items: start; }
.panel { min-width: 0; background: var(--jk-color-surface); border: 1px solid var(--jk-color-border); border-radius: var(--jk-radius-panel); }
.panel-heading { padding: var(--jk-space-4); border-bottom: 1px solid var(--jk-color-border); }
.panel-heading h2, .panel-heading p { margin-bottom: 0; }
.queue-list { display: grid; gap: 1px; background: var(--jk-color-border); }
.queue-item { width: 100%; min-height: 88px; padding: var(--jk-space-3) var(--jk-space-4); border: 0; background: var(--jk-color-surface); text-align: left; cursor: pointer; }
.queue-item:hover { background: var(--jk-color-canvas); }
.queue-item[aria-current="true"] { border-left: 4px solid var(--jk-color-focus); background: var(--jk-color-canvas); padding-left: var(--jk-space-3); }
.queue-row { display: flex; justify-content: space-between; gap: var(--jk-space-3); margin-bottom: 3px; }
.case-id, .amount { font-variant-numeric: tabular-nums; font-weight: 700; }
.customer { font-weight: 650; }
.state { display: block; margin-top: 4px; color: var(--jk-color-muted); }
.state-warning { color: var(--jk-color-warning); font-weight: 700; }
.detail-body { padding: var(--jk-space-4); }
.case-summary { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--jk-space-4); padding-bottom: var(--jk-space-4); border-bottom: 1px solid var(--jk-color-border); }
.case-summary h2 { margin-bottom: 4px; font-size: 20px; }
.price { font-size: 20px; font-weight: 750; font-variant-numeric: tabular-nums; white-space: nowrap; }
.request { margin: var(--jk-space-4) 0; }
.status-alert { padding: var(--jk-space-3); margin-bottom: var(--jk-space-4); border: 1px solid var(--jk-color-warning); border-radius: var(--jk-radius-control); color: var(--jk-color-warning); font-weight: 650; }
.section { padding-top: var(--jk-space-4); margin-top: var(--jk-space-4); border-top: 1px solid var(--jk-color-border); }
.evidence-list { padding: 0; margin: 0; list-style: none; }
.evidence-list li { display: grid; grid-template-columns: 22px 1fr; gap: var(--jk-space-2); padding: var(--jk-space-2) 0; }
.evidence-mark { font-weight: 800; color: var(--jk-color-success); }
.evidence-missing .evidence-mark, .evidence-missing strong { color: var(--jk-color-warning); }
.policy { padding: var(--jk-space-3); border-left: 3px solid var(--jk-color-focus); background: var(--jk-color-canvas); }
.policy p { margin-bottom: 0; }
.decision-panel { position: sticky; top: var(--jk-space-4); }
.decision-body { padding: var(--jk-space-4); }
.decision-options { display: grid; gap: var(--jk-space-2); }
.decision-button { min-height: 48px; padding: var(--jk-space-3); border: 1px solid var(--jk-color-border); border-radius: var(--jk-radius-control); background: var(--jk-color-surface); text-align: left; font-weight: 700; cursor: pointer; }
.decision-button:hover { border-color: var(--jk-color-focus); }
.decision-button[aria-pressed="true"] { border: 2px solid var(--jk-color-warning); color: var(--jk-color-warning); background: var(--jk-color-canvas); }
.field { display: grid; gap: var(--jk-space-2); margin-top: var(--jk-space-4); }
.field label { font-weight: 700; }
.field select, .field textarea { width: 100%; border: 1px solid var(--jk-color-border); border-radius: var(--jk-radius-control); background: var(--jk-color-surface); }
.field select { min-height: 44px; padding: 0 var(--jk-space-3); }
.field textarea { min-height: 112px; padding: var(--jk-space-3); resize: vertical; }
.handoff-preview { margin-top: var(--jk-space-4); padding: var(--jk-space-3); border: 1px solid var(--jk-color-receipt); border-radius: var(--jk-radius-control); }
.handoff-preview strong { color: var(--jk-color-receipt); }
.send-button { width: 100%; min-height: 48px; margin-top: var(--jk-space-4); padding: var(--jk-space-3) var(--jk-space-4); border: 1px solid var(--jk-color-focus); border-radius: var(--jk-radius-control); background: var(--jk-color-focus); color: var(--jk-color-surface); font-weight: 750; cursor: pointer; }
button:focus-visible, select:focus-visible, textarea:focus-visible { outline: 2px solid var(--jk-color-focus); outline-offset: 2px; box-shadow: var(--jk-focus-ring); }
button:disabled, select:disabled, textarea:disabled { border-color: var(--jk-color-disabled); color: var(--jk-color-disabled); cursor: not-allowed; }
@media (max-width: 980px) { .workspace { grid-template-columns: 230px minmax(0, 1fr); } .decision-panel { position: static; grid-column: 1 / -1; } }
@media (max-width: 680px) { .refund-workbench { padding: var(--jk-space-3); } .page-header { align-items: flex-start; flex-direction: column; } .workspace { grid-template-columns: 1fr; } .decision-panel { grid-column: auto; } .queue-list { grid-template-columns: 1fr; } .case-summary { flex-direction: column; } .price { font-size: 18px; } }

